export declare const verifyCorrectness: (
/** Child correctness to wrap. */
correctness: Correctness) => CorrectnessResult;
/** Apply the `j:` wrapper to a correctness type. */
export declare const nonZeroCorrectness: (
/** Child correctness to wrap. */
correctness: Correctness) => CorrectnessResult;
/** Apply the `n:` wrapper to a correctness type. */
export declare const zeroNotEqualCorrectness: (
/** Child correctness to wrap. */
correctness: Correctness) => CorrectnessResult;
